import React, { useState, useEffect } from 'react';

function Analytics() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState("ALL");

  useEffect(() => {
    fetch('http://localhost:5000/api/analytics')
      .then(res => res.json())
      .then(d => {
        setData(d);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  if (loading) return <h3>Loading Analytics Data...</h3>;
  if (!data) return <h3 style={{ color: 'red' }}>Error: Backend Not Connected</h3>;

  // ✅ THE CRITICAL FIX: Synchronized filtering
  const filteredUAVs = (data.uavs || []).filter(u => {
    if (filter === "ALL") return true;
    // Normalizes "Pass" vs "Passed" and "Fail" vs "Failed"
    return u.status.toLowerCase().includes(filter.toLowerCase().substring(0, 4));
  });

  return (
    <div style={{ padding: '20px', backgroundColor: '#f4f7f6', minHeight: '100vh' }}>
      <h1>Quality Analytics Dashboard</h1>

      {/* 📊 BIG DATA INSIGHTS PANEL */}
      <div style={{ display: 'flex', gap: '20px', marginBottom: '20px' }}>
        <div style={{ flex: 1, padding: '20px', background: '#fff', borderRadius: '8px', boxShadow: '0 2px 5px rgba(0,0,0,0.1)' }}>
          <h3>First Pass Yield (FPY)</h3>
          <h2 style={{ color: data.yieldRate > 80 ? 'green' : 'orange' }}>{data.yieldRate}%</h2>
          <p>Target: 95.0%</p>
        </div>
        <div style={{ flex: 2, padding: '20px', background: '#fff', borderRadius: '8px', boxShadow: '0 2px 5px rgba(0,0,0,0.1)' }}>
          <h3>Process Health</h3>
          <p>Current system is <strong>{data.yieldRate > 85 ? 'OPTIMIZED' : 'REQUIRES ATTENTION'}</strong></p>
          <div style={{ height: '10px', width: '100%', background: '#eee', borderRadius: '5px' }}>
             <div style={{ height: '100%', width: `${data.yieldRate}%`, background: 'green', borderRadius: '5px' }}></div>
          </div>
        </div>
      </div>

      {/* 🗂 KPI CARDS */}
      <div style={{ display: 'flex', gap: '15px', marginBottom: '30px' }}>
        {[
          { label: 'Total', val: data.total, col: '#333', type: 'ALL' },
          { label: 'Passed', val: data.passed, col: 'green', type: 'Pass' },
          { label: 'Failed', val: data.failed, col: 'red', type: 'Fail' },
          { label: 'In Progress', val: data.inProgress, col: 'orange', type: 'In Progress' }
        ].map(k => (
          <div key={k.label} onClick={() => setFilter(k.type)} style={{
            flex: 1, textAlign: 'center', padding: '15px', borderRadius: '8px', cursor: 'pointer',
            border: `2px solid ${k.col}`, background: filter === k.type ? '#f0f0f0' : 'white'
          }}>
            <h2 style={{ color: k.col }}>{k.val}</h2>
            <b>{k.label}</b>
          </div>
        ))}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
        {/* LIST VIEW */}
        <div style={{ background: '#fff', padding: '20px', borderRadius: '8px' }}>
          <h3>UAV Status List ({filter})</h3>
          <table width="100%" border="1" cellPadding="10" style={{ borderCollapse: 'collapse' }}>
            <thead><tr style={{ background: '#eee' }}><th>UAV ID</th><th>Status</th></tr></thead>
            <tbody>
              {filteredUAVs.length === 0 ? <tr><td colSpan="2">No records found</td></tr> :
                filteredUAVs.map(u => (
                  <tr key={u.id}>
                    <td>{u.id}</td>
                    <td style={{ color: u.status === 'Pass' ? 'green' : 'red', fontWeight: 'bold' }}>{u.status}</td>
                  </tr>
                ))
              }
            </tbody>
          </table>
        </div>

        {/* BOTTLENECK ANALYTICS */}
        <div style={{ background: '#fff', padding: '20px', borderRadius: '8px' }}>
          <h3>Defect Distribution (Root Cause)</h3>
          {data.stageData.map(s => (
            <div key={s.name} style={{ marginBottom: '15px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span>{s.name}</span>
                <span>{s.defects} Defects</span>
              </div>
              <div style={{ height: '8px', background: '#eee', borderRadius: '4px', marginTop: '5px' }}>
                <div style={{ 
                  height: '100%', 
                  width: `${Math.min((s.defects / data.total) * 100, 100)}%`, 
                  background: s.defects > 5 ? '#dc3545' : '#007bff',
                  borderRadius: '4px' 
                }}></div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default Analytics;
